mapper.select:


    inner join sys_user u on u.user_name = tmergedelivery.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tmergedelivery.del_flag = '0'
     and tmergedelivery.code like concat('%', #{code}, '%')
     and tmergedelivery.status = #{status}
    and tmergedelivery.allocate_flag = #{allocateFlag}


${params.dataScope}
